style.css:
@-moz-document domain("youtube.com") {
:root {
    /* change these colors to customize the vibe */
    --my-bg: #08060d;
    --my-panel: #160d20;
    --my-card: #21112e;
    --my-pink: #ff20b8;
    --my-purple: #a020f0;
    --my-green: #39ff14;
    --my-text: #fff0ff;
  }

  /* atmospheric background */
  html,
  body,
  ytd-app {
    background:
      radial-gradient(ellipse at 15% 5%, #32104455, transparent 45%),
      radial-gradient(ellipse at 85% 65%, #123b1740, transparent 45%),
      var(--my-bg) !important;
    color: var(--my-text) !important;
  }

  /* top navigation bar */
  ytd-masthead {
    background: #100a18 !important;
    border-bottom: 2px solid var(--my-purple) !important;
    box-shadow: 0 3px 18px #a020f044 !important;
  }

  /* sidebar */
  ytd-guide-renderer,
  ytd-mini-guide-renderer,
  #guide-content {
    background: var(--my-panel) !important;
  }

  /* sidebar hover effects */
  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: #382044 !important;
    border-left: 3px solid var(--my-green) !important;
    border-radius: 8px !important;
  }

  /* video cards */
  ytd-rich-item-renderer {
    background: linear-gradient(145deg, #261332, #140b1d) !important;
    border: 1px solid #702c83 !important;
    border-radius: 15px !important;
    overflow: hidden !important;
    padding: 6px !important;
    box-shadow: 0 0 12px #a020f022 !important;
    transition: all 0.2s ease !important;
  }

  /* neon hover glow */
  ytd-rich-item-renderer:hover {
    border-color: var(--my-green) !important;
    box-shadow:
      0 0 8px #39ff1466,
      0 0 22px #ff20b844 !important;
    transform: translateY(-3px) !important;
  }

  /* video thumbnails */
  ytd-thumbnail {
    border-radius: 11px !important;
    overflow: hidden !important;
    border: 1px solid #a020f055 !important;
  }

  /* video titles */
  #video-title {
    color: var(--my-text) !important;
    font-weight: 900 !important;
  }

  /* channel names and metadata */
  #metadata,
  #metadata-line,
  ytd-video-meta-block {
    color: #c4a6d4 !important;
  }

  /* neon links */
  a {
    color: var(--my-pink) !important;
  }

  /* search bar */
  ytd-searchbox {
    background: #1b1025 !important;
    border: 2px solid var(--my-purple) !important;
    border-radius: 20px !important;
    box-shadow: 0 0 12px #a020f044 !important;
  }

  /* category buttons */
  yt-chip-cloud-chip-renderer {
    background: #21132d !important;
    border: 1px solid var(--my-purple) !important;
    border-radius: 9px !important;
    color: var(--my-text) !important;
    font-weight: bold !important;
  }

  yt-chip-cloud-chip-renderer:hover {
    background: #421449 !important;
    border-color: var(--my-pink) !important;
    box-shadow: 0 0 10px #ff20b855 !important;
  }

  yt-chip-cloud-chip-renderer[chip-style="STYLE_HOME_FILTER"]:first-child {
    background: var(--my-pink) !important;
    color: #100610 !important;
  }

  /* buttons */
  yt-button-shape button,
  ytd-button-renderer button {
    border-radius: 10px !important;
  }

  /* selection highlight */
  ::selection {
    background: var(--my-pink) !important;
    color: #09070d !important;
  }

  /* neon scrollbar */
  ::-webkit-scrollbar {
    width: 9px !important;
  }

  ::-webkit-scrollbar-track {
    background: var(--my-bg) !important;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(
      var(--my-pink),
      var(--my-purple),
      var(--my-green)
    ) !important;
    border-radius: 10px !important;
  }
}
